    // Check if the polygon is convex by verifying that all internal angles are consistent
    // and no two conditions are reversed for the same result across all vertices
    int n = polygon.size();
    if (n < 3) {
        return false;
    }

    // Use the cross product to determine the orientation of the polygon
    // and check if all of them are turned the same way (left turn, right turn, or collinear)
    // and if the polygon is convex

    // For each triplet of consecutive points, check the orientation
    // if the three consecutive points are not all turned to the left or right, the polygon is not convex
    for (int i=0; i<n; ++i) {
        // Use the sign of the cross product to check the orientation
        int prevOrient = 0;
        int nextOrient = 0;
        int isConvex = 0;
        for (int j=0; j<n; ++j) {
            if (polygon[j].x() == polygon[(j+1) % n].x() && polygon[j].y() == polygon[(j+1) % n].y()) {
                continue;
            }
            if (polygon[j].x() == polygon[(j+1) % n].x() && polygon[j].y() == polygon[(j+1) % n].y()) {
                continue;
            }
            if (polygon[j].x() == polygon[(j+1) % n].x() && polygon[j].y() == polygon[(j+1) % n].y()) {
                isConvex = 1;
            }
        }
        if (isConvex) {
            return true;
        }
        if (prevOrient == 0) {
            // ... (truncated)  - no change in orientation
            return true;
        }
        if (nextOrient != 0) {
            // ... (truncated)  - orientation changes, not convex
            return true;
        }
        return false;
    }
